describe('Head Butt Turtle mob skill',function()
 it('uses its blunt physical plan and applies random Accuracy Down only after processing',function()
  local butt=require('scripts/actions/mobskills/head_butt_turtle');local move,process,effect,random=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove,math.random;local params,damage,accuracy=nil,nil,nil;local mob={getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.BLUNT}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(_,_,...)accuracy={...}end;math.random=function(min,max)assert(min==120 and max==180);return 150 end
  assert(butt.onMobSkillCheck(target,mob,{})==0 and butt.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==1 and params.fTP[2]==1 and params.fTP[3]==1 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.BLUNT and params.shadowBehavior==xi.mobskills.shadowBehavior.NUMSHADOWS_1 and damage==nil and accuracy==nil);xi.mobskills.processDamage=function()return true end;butt.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove,math.random=move,process,effect,random;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.PHYSICAL and damage[4]==xi.damageType.BLUNT);assert(accuracy[1]==xi.effect.ACCURACY_DOWN and accuracy[2]==40 and accuracy[3]==0 and accuracy[4]==150)
 end)
end)
